#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Create a temporary sandbox\nSANDBOX=$(mktemp -d)\nSSH_DIR=\"$SANDBOX/.ssh\"\nmkdir -p \"$SSH_DIR\"\n\n# Create dummy existing keys\necho \"OLD_PRIVATE\" > \"$SSH_DIR/id_ed25519\"\necho \"OLD_PUBLIC\" > \"$SSH_DIR/id_ed25519.pub\"\n\n# Mock ssh-keygen\nMOCK_BIN=$SANDBOX/mock_bin\nmkdir -p \"$MOCK_BIN\"\ncat > \"$MOCK_BIN/ssh-keygen\" <<'EOF'\n#!/usr/bin/env bash\n# Simple deterministic mock of ssh-keygen\nwhile [[ $# -gt 0 ]]; do\n  case $1 in\n    -t) KEY_TYPE=$2; shift 2;;\n    -b) BITS=$2; shift 2;;\n    -C) COMMENT=$2; shift 2;;\n    -f) OUTFILE=$2; shift 2;;\n    -N) PASS=$2; shift 2;;\n    *) shift;;\n  esac\n done\n# Write deterministic private and public key files\necho \"PRIVATE_KEY_${KEY_TYPE}\" > \"${OUTFILE}\"\necho \"PUBLIC_KEY_${KEY_TYPE} ${COMMENT}\" > \"${OUTFILE}.pub\"\nEOF\nchmod +x \"$MOCK_BIN/ssh-keygen\"\n\n# Prepend mock bin to PATH\nexport PATH=\"$MOCK_BIN:$PATH\"\n\n# Run the utility\nSCRIPT_DIR=$(cd "$(dirname \"${BASH_SOURCE[0]}\")/../src" && pwd)\nbash \"$SCRIPT_DIR/rotate_ssh_keys.sh\" --ssh-dir \"$SSH_DIR\" --key-type ed25519 --comment \"test@example.com\"\n\n# Verify backup files exist\nbackup_private=$(ls \"$SSH_DIR/id_ed25519.bak.*\" 2>/dev/null || true)\nbackup_public=$(ls \"$SSH_DIR/id_ed25519.pub.bak.*\" 2>/dev/null || true)\nif [[ -z \"$backup_private\" || -z \"$backup_public\" ]]; then\n  echo \"Backup files missing\"; exit 1;\nfi\n\n# Verify new key contents\nif ! grep -q \"PRIVATE_KEY_ed25519\" \"$SSH_DIR/id_ed25519\"; then\n  echo \"New private key content incorrect\"; exit 1;\nfi\nif ! grep -q \"PUBLIC_KEY_ed25519 test@example.com\" \"$SSH_DIR/id_ed25519.pub\"; then\n  echo \"New public key content incorrect\"; exit 1;\nfi\n\n# Verify authorized_keys contains the new public key\nif ! grep -q \"PUBLIC_KEY_ed25519 test@example.com\" \"$SSH_DIR/authorized_keys\"; then\n  echo \"authorized_keys not updated\"; exit 1;\nfi\n\necho "All tests passed."\n
